<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';
type Row=Record<string,any>;
type Field={key:string;label:string;type?:string;optional?:boolean};
type Screen={id:string;name:string;group:string;url?:string;admin?:boolean;super?:boolean;columns?:string[];fields?:Field[];create?:string;note:string};
const screens:Screen[]=[
 {id:'home',name:'工作台',group:'开始',note:'按组织、账号、授权的顺序配置，所有操作以服务端校验结果为准。'},
 {id:'portal',name:'应用门户',group:'开始',note:'本地 OIDC 演示入口。先启动两个演示客户端；它们不是企业真实 OA 或 HR 系统。'},
 {id:'users',name:'用户管理',group:'基础管理',admin:true,url:'/api/platform/users',columns:['id','username','display_name','enabled','department_id','post_id'],note:'导入员工默认无密码、无角色。重置密码后须由员工修改，停用和强制下线会撤销会话。',create:'/api/users',fields:[{key:'username',label:'用户名'},{key:'displayName',label:'姓名'}]},
 {id:'roles',name:'角色管理',group:'基础管理',admin:true,url:'/api/platform/organization/roles',columns:['id','code','name','enabled','department_id'],note:'多角色权限取并集。部门管理员只维护所属部门角色及被委派的权限。'},
 {id:'permissions',name:'权限管理',group:'基础管理',super:true,url:'/api/permissions',columns:['id','code','name','menuPath','systemId'],note:'权限点由业务系统定义。本人范围权限不能代替业务系统的数据范围判断。',create:'/api/permissions',fields:[{key:'systemId',label:'业务系统编号',type:'number'},{key:'code',label:'权限编码'},{key:'name',label:'权限名称'},{key:'menuPath',label:'菜单或资源路径'}]},
 {id:'systems',name:'应用管理',group:'基础管理',super:true,url:'/api/systems',columns:['id','code','name','baseUrl','enabled'],note:'业务系统目录与 OIDC 客户端注册是不同配置。本地已注册两个固定回调的 PKCE 演示客户端。',create:'/api/systems',fields:[{key:'code',label:'系统编码'},{key:'name',label:'系统名称'},{key:'baseUrl',label:'入口 URL',optional:true}]},
 {id:'departments',name:'部门管理',group:'组织数据',super:true,url:'/api/company/departments',columns:['id','name','parent_id','manager_name','manager_username'],note:'部门形成组织树。负责人需明确关联本部门员工，不按重名自动指定管理员。',create:'/api/platform/organization/departments',fields:[{key:'name',label:'部门名称'},{key:'parentId',label:'上级部门编号',type:'number',optional:true},{key:'managerId',label:'负责人账号编号',type:'number',optional:true}]},
 {id:'posts',name:'岗位管理',group:'组织数据',super:true,url:'/api/company/posts',columns:['id','name','role_id','enabled'],note:'岗位对应一个同名角色。应用权限模板会增加岗位角色权限，但不会自动给员工分配角色。',create:'/api/platform/organization/posts',fields:[{key:'name',label:'岗位名称'},{key:'code',label:'角色编码'},{key:'departmentId',label:'受管部门编号',type:'number',optional:true}]},
 {id:'imports',name:'三表导入',group:'组织数据',super:true,url:'/api/company/imports',columns:['id','created_at','departments','employees','functions'],note:'依次选择部门、员工、权限清单。先预览全部错误与警告，再确认整批导入；重复文件不会重复建数据。'},
 {id:'catalog',name:'功能权限目录',group:'组织数据',super:true,url:'/api/company/catalog',columns:['id','system','module','name','permissions'],note:'按系统、模块、功能、操作展示来源表。清单中的“无”不授权，“全部”只展开已有的具体操作。'},
 {id:'dictionary',name:'字典管理',group:'组织数据',super:true,url:'/api/platform/dictionary',columns:['id','category','code','name'],note:'维护业务分类和字典项，不通过字典绕过账号或授权规则。',create:'/api/platform/dictionary',fields:[{key:'category',label:'分类编码'},{key:'code',label:'项目编码'},{key:'name',label:'显示名称'}]},
 {id:'sessions',name:'在线会话',group:'运行记录',url:'/api/platform/sessions',columns:['id','user_id','issued_at','expires_at'],note:'展示本人会话。撤销当前会话后需要重新登录；管理员可在用户管理中强制指定用户下线。'},
 {id:'audit',name:'操作日志',group:'运行记录',admin:true,url:'/api/platform/audit',columns:['id','created_at','actor_id','kind','target','result'],note:'审计记录只读。部门管理员只能查看绑定部门的记录。'},
 {id:'loginlogs',name:'登录日志',group:'运行记录',admin:true,url:'/api/platform/audit?kind=LOGIN',columns:['id','created_at','actor_id','target','result'],note:'显示认证成功和失败事件，不记录密码或令牌。'},
 {id:'approvals',name:'权限申请',group:'运行记录',url:'/api/platform/self/applications',columns:['id','request_id','role_id','decision','created_at'],note:'申请只创建待审批记录，不直接授权。由本地 OA 演示端发送签名回调执行审批结果。'},
 {id:'sync',name:'同步记录',group:'运行记录',super:true,url:'/api/platform/integrations',columns:['id','source','request_id','result','user_id','created_at'],note:'HR 入职、调岗、离职与 OA 回调使用签名和幂等请求编号。重复事件不重复执行。'},
 {id:'profile',name:'个人中心',group:'本人',note:'修改密码需验证旧密码，修改成功后撤销旧会话。'},
 {id:'mypermissions',name:'我的权限',group:'本人',columns:['id','code','name','systemId'],note:'当前登录身份的有效权限，来自所有启用角色与启用业务系统的并集。'},
 {id:'expenses',name:'报销权限演示',group:'本人',note:'返回固定演示数据，仅用于展示 expense:list 权限校验。不是实际报销业务系统。'},
 {id:'403',name:'访问受限',group:'状态',note:'403：当前登录仍有效，但没有此操作权限。请联系管理员核对授权。'},
 {id:'404',name:'页面不存在',group:'状态',note:'404：找不到这个页面。请从左侧导航重新进入。'}
];
const labels:Row={id:'编号',username:'用户名',display_name:'姓名',enabled:'状态',department_id:'部门编号',post_id:'岗位编号',code:'编码',name:'名称',menuPath:'资源路径',systemId:'系统编号',baseUrl:'入口',parent_id:'上级部门',manager_name:'负责人姓名',manager_username:'负责人账号',role_id:'角色编号',created_at:'创建时间',departments:'部门数',employees:'员工数',functions:'功能数',system:'业务系统',module:'模块',permissions:'操作权限',category:'分类',user_id:'账号编号',issued_at:'签发时间',expires_at:'过期时间',actor_id:'操作人',kind:'事件类型',target:'对象',result:'结果',request_id:'请求编号',decision:'审批状态',source:'来源'};
const token=ref(sessionStorage.getItem('permission-token')||''),identity=ref<Row>({}),username=ref(''),password=ref(''),screenId=ref(location.hash.slice(1)||'home');
const loading=ref(false),busy=ref(false),message=ref(''),error=ref(false),rows=ref<Row[]>([]),total=ref(0),page=ref(0),editor=ref(false),form=ref<Row>({}),selected=ref<Row|null>(null),mode=ref(''),roleId=ref(''),permissionId=ref(''),newPassword=ref(''),oldPassword=ref(''),templateName=ref('普通员工'),preview=ref<Row|null>(null),ack=ref(false),files=ref<Record<string,File>>({}),result=ref<any>(null),q=ref('');
const screen=computed(()=>screens.find(s=>s.id===screenId.value)||screens.find(s=>s.id==='404')!);
const visible=computed(()=>screens.filter(s=>s.group!=='状态'&&(!s.super||identity.value.superAdmin)&&(!s.admin||identity.value.superAdmin||identity.value.departmentAdmin)));
const allowed=computed(()=>(!screen.value.super||identity.value.superAdmin)&&(!screen.value.admin||identity.value.superAdmin||identity.value.departmentAdmin));
function notify(text:string,bad=false){message.value=text;error.value=bad;}
async function api(path:string,method='GET',body?:any){
 const response=await fetch(path,{method,headers:{...(token.value?{Authorization:`Bearer ${token.value}`} :{}),...(body&&!(body instanceof FormData)?{'Content-Type':'application/json'}:{})},body:body instanceof FormData?body:body?JSON.stringify(body):undefined});
 const data=response.status===204?null:await response.text().then(t=>{try{return t?JSON.parse(t):null}catch{return null}});
 if(!response.ok){if(response.status===401){token.value='';sessionStorage.removeItem('permission-token');identity.value={};}throw new Error((response.status===401?'登录失效，请重新登录。':response.status===403?'无权执行此操作。':'')+(data?.message||`请求失败（${response.status}）`));}return data;
}
async function run(action:()=>Promise<void>){busy.value=true;try{await action()}catch(e){notify(e instanceof Error?e.message:'操作失败，请重试',true)}finally{busy.value=false}}
async function refresh(){
 loading.value=true;rows.value=[];try{if(!allowed.value)return;let data:any;
 if(screen.value.id==='mypermissions'){identity.value=await api('/api/platform/self');data=identity.value.permissions;}
 else if(screen.value.url){let url=screen.value.url;if(['users','catalog','audit','loginlogs'].includes(screen.value.id))url+=(url.includes('?')?'&':'?')+`page=${page.value}&size=25`+(screen.value.id==='catalog'?`&q=${encodeURIComponent(q.value)}`:'');data=await api(url);}
 if(data){rows.value=Array.isArray(data)?data:data.items||[];total.value=Array.isArray(data)?data.length:data.total||0;}
 }catch(e){notify((e as Error).message,true)}finally{loading.value=false}}
async function go(id:string){screenId.value=id;location.hash=id;page.value=0;editor.value=false;selected.value=null;result.value=null;message.value='';await refresh();}
async function login(){await run(async()=>{const data=await api('/api/auth/login','POST',{username:username.value,password:password.value});token.value=data.accessToken;sessionStorage.setItem('permission-token',token.value);password.value='';identity.value=await api('/api/platform/self');await go(identity.value.mustChangePassword?'profile':'home');if(identity.value.mustChangePassword)notify('请先修改初始密码，其他功能暂不可用。');});}
async function logout(){await run(async()=>{await api('/api/auth/logout','POST');token.value='';sessionStorage.removeItem('permission-token');identity.value={};notify('已退出登录');});}
function display(key:string,value:any){if(key==='enabled')return value?'启用':'停用';if(value==null||value==='')return '—';if(Array.isArray(value))return value.map(v=>v.action||v.name||v.code).join(' / ');if(typeof value==='object')return JSON.stringify(value);return String(value);}
function create(){form.value={};editor.value=true;selected.value=null;mode.value='create';}
function action(row:Row,kind:string){selected.value=row;editor.value=true;mode.value=kind;roleId.value='';permissionId.value='';newPassword.value='';form.value={...row,displayName:row.display_name,parentId:row.parent_id};}
async function save(){await run(async()=>{
 let url=screen.value.create||'',method='POST',body:any={};
 if(mode.value==='create'){for(const f of screen.value.fields||[]){const v=form.value[f.key];body[f.key]=v==null||v===''?null:f.type==='number'?Number(v):v;}}
 else {const id=selected.value!.id;
 if(mode.value==='password'){url=`/api/platform/users/${id}/password`;body={password:newPassword.value};}
 else if(mode.value==='grant'||mode.value==='revoke'){url=`/api/platform/users/${id}/roles/${Number(roleId.value)}`;method=mode.value==='grant'?'PUT':'DELETE';body=undefined;}
 else if(mode.value==='grantPermission'||mode.value==='revokePermission'){url=`/api/platform/organization/roles/${id}/permissions/${Number(permissionId.value)}`;method=mode.value==='grantPermission'?'PUT':'DELETE';body=undefined;}
 else if(mode.value==='template'){url=`/api/company/posts/${id}/template`;body={name:templateName.value};}
 else if(mode.value==='edit'){url=`/api/${screen.value.id}/${id}`;method='PUT';body={...form.value};if(screen.value.id==='users')body={displayName:form.value.displayName,enabled:form.value.enabled};}
 }
 await api(url,method,body);editor.value=false;await refresh();notify('操作成功，列表已刷新。');
 });}
async function immediate(row:Row,kind:string){if(!confirm(kind==='delete'?'确认删除此账号？账号将停用并回收角色和会话。':kind==='offline'?'确认撤销该账号的全部会话？':'确认执行此操作？'))return;await run(async()=>{let url='',method='POST',body:any;
 if(kind==='state'){url=`/api/platform/users/${row.id}/state`;method='PUT';body={enabled:!row.enabled};}
 if(kind==='delete'){url=`/api/platform/users/${row.id}`;method='DELETE';}
 if(kind==='offline')url=`/api/platform/users/${row.id}/offline`;
 if(kind==='session'){url=`/api/platform/sessions/${row.id}`;method='DELETE';}
 await api(url,method,body);await refresh();notify('操作成功，数据已刷新。');});}
async function upload(){await run(async()=>{const data=new FormData();for(const key of ['departments','employees','permissions']){if(!files.value[key])throw new Error('请选择全部三份 XLSX 文件');data.append(key,files.value[key]);}preview.value=await api('/api/company/imports/preview','POST',data);ack.value=false;notify('预览完成，请检查错误与警告。');});}
async function commit(){await run(async()=>{result.value=await api('/api/company/imports/commit','POST',{previewId:preview.value!.previewId,acknowledgeWarnings:ack.value});preview.value=null;await refresh();notify('导入成功，员工未被自动授权。');});}
function fileChange(key:string,event:Event){const f=(event.target as HTMLInputElement).files?.[0];if(f)files.value[key]=f;preview.value=null;}
async function changePassword(){await run(async()=>{await api('/api/platform/self/password','POST',{oldPassword:oldPassword.value,newPassword:newPassword.value});token.value='';sessionStorage.removeItem('permission-token');oldPassword.value='';newPassword.value='';notify('密码已更新，请使用新密码登录。');});}
onMounted(async()=>{if(token.value)await run(async()=>{identity.value=await api('/api/platform/self');await refresh();});window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(id!==screenId.value)void go(id)});});
</script>

<template>
 <header class="top"><div><strong>统一权限管理平台</strong><span class="muted ml-4 text-sm">市政公司 · 一期本地演示</span></div><div v-if="token" class="actions"><span class="badge">{{identity.superAdmin?'超级管理员':identity.departmentAdmin?'部门管理员':'普通用户'}}</span><button @click="logout" :disabled="busy">退出登录</button></div></header>
 <section v-if="!token" class="login"><div class="mark">UNIFIED ACCESS</div><h1>登录管理平台</h1><p class="muted">使用统一账号或唯一手机号登录，访问被授予的应用与功能。</p><div v-if="message" role="alert" :class="['notice',{error}]">{{message}}</div><form @submit.prevent="login"><label>账号或手机号<input v-model="username" required maxlength="64" autocomplete="username"></label><label>密码<input v-model="password" type="password" required autocomplete="current-password"></label><button class="primary" :disabled="busy">{{busy?'正在验证…':'登录'}}</button></form><p class="muted text-sm">首次管理员使用启动时配置的账号。导入员工需先由管理员设置密码。</p></section>
 <div v-else class="shell"><nav aria-label="主导航"><template v-for="(item,i) in visible" :key="item.id"><div v-if="i===0||visible[i-1]?.group!==item.group" class="section-label">{{item.group}}</div><button :class="{active:screen.id===item.id}" :aria-current="screen.id===item.id?'page':undefined" @click="go(item.id)">{{item.name}}</button></template></nav><main>
 <div class="toolbar"><div><p class="muted text-sm mb-2">{{screen.group}} / {{screen.name}}</p><h1>{{screen.name}}</h1></div><button v-if="screen.url||screen.id==='mypermissions'" @click="refresh" :disabled="loading">刷新</button></div>
 <div v-if="message" role="alert" :class="['notice',{error}]">{{message}}</div><p class="muted mb-6">{{screen.note}}</p>
 <div v-if="!allowed" class="notice error">403：当前账号没有此页面的管理权限。</div>
 <template v-else>
 <ol v-if="screen.id==='home'" class="steps"><li><strong>准备组织与员工数据</strong><p>管理员上传三份表单，核对部门、岗位、功能目录及未确认项。</p><button v-if="identity.superAdmin" @click="go('imports')">进入三表导入</button></li><li><strong>配置岗位角色和权限</strong><p>模板先应用到岗位角色，再明确分配给员工。角色名称不决定平台管理身份。</p><button v-if="identity.superAdmin||identity.departmentAdmin" @click="go('roles')">管理角色</button></li><li><strong>以实际身份验证访问</strong><p>查看有效权限，测试授权、回收和注销后的不同结果。</p><button @click="go('mypermissions')">查看我的权限</button></li></ol>
 <section v-if="screen.id==='portal'"><button class="primary" :disabled="busy" @click="run(async()=>{await api('/api/platform/self/sso','POST');notify('统一登录会话已建立，可以打开两个客户端验证免登。')})">使用当前身份建立单点登录会话</button><div class="portal"><article v-for="app in [{name:'OA 演示客户端',port:18101},{name:'HR 演示客户端',port:18102}]" :key="app.port"><h2>{{app.name}}</h2><p class="muted">授权码模式 + PKCE，通过统一认证中心登录。</p><a class="button" :href="`http://127.0.0.1:${app.port}/`" target="_blank" rel="noopener">打开本地演示</a></article></div></section>
 <form v-if="screen.id==='imports'" @submit.prevent="upload" class="mb-7"><div class="fields"><label v-for="f in [{key:'departments',label:'部门信息表'},{key:'employees',label:'员工信息表'},{key:'permissions',label:'应用软件功能权限清单'}]" :key="f.key">{{f.label}}<input type="file" accept=".xlsx" required @change="fileChange(f.key,$event)"></label></div><button class="primary" :disabled="busy">{{busy?'正在处理…':'校验并预览'}}</button></form>
 <section v-if="preview" class="mb-7"><h2>导入预览</h2><p>部门 {{preview.counts.departments}} · 员工 {{preview.counts.employees}} · 岗位 {{preview.counts.posts}} · 系统 {{preview.counts.systems}} · 功能 {{preview.counts.functions}}</p><p>错误 {{preview.errorCount}} 项，警告 {{preview.warningCount}} 项（最多展示各 200 项）。</p><ul><li v-for="(issue,i) in [...preview.errors,...preview.warnings]" :key="i" class="my-2">{{issue.file||issue.sheet}} {{issue.row?`第 ${issue.row} 行`:''}}：{{issue.message}}</li></ul><label class="check my-4"><input type="checkbox" v-model="ack">已核对警告，确认未确定权限不授予，新员工不自动授权。</label><button class="primary" :disabled="busy||!ack||preview.errorCount>0" @click="commit">确认整批导入</button></section>
 <form v-if="screen.id==='catalog'" @submit.prevent="page=0;refresh()" class="actions mb-5"><input v-model="q" placeholder="搜索系统、模块或功能" aria-label="搜索功能目录" style="max-width:400px"><button>搜索</button></form>
 <div v-if="screen.create&&identity.superAdmin" class="mb-5"><button class="primary" @click="create">新增{{screen.name.replace('管理','')}}</button></div>
 <p v-if="loading" role="status" class="notice">正在读取数据…</p>
 <template v-else-if="screen.url||screen.id==='mypermissions'"><div class="table-wrap"><table><thead><tr><th v-for="col in screen.columns" :key="col">{{labels[col]||col}}</th><th v-if="['users','roles','posts','sessions','systems','permissions'].includes(screen.id)">操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td v-for="col in screen.columns" :key="col">{{display(col,row[col])}}</td><td v-if="['users','roles','posts','sessions','systems','permissions'].includes(screen.id)"><div class="actions"><template v-if="screen.id==='users'"><button v-if="identity.superAdmin" @click="action(row,'edit')">编辑</button><button @click="action(row,'password')">设置密码</button><button @click="action(row,'grant')">分配角色</button><button @click="action(row,'revoke')">回收角色</button><button @click="immediate(row,'state')">{{row.enabled?'停用':'启用'}}</button><button @click="immediate(row,'offline')">下线</button><button class="danger" @click="immediate(row,'delete')">删除</button></template><template v-if="screen.id==='roles'"><button @click="action(row,'grantPermission')">分配权限</button><button @click="action(row,'revokePermission')">回收权限</button></template><button v-if="screen.id==='posts'" @click="action(row,'template')">应用模板</button><button v-if="screen.id==='sessions'" @click="immediate(row,'session')">撤销会话</button><button v-if="['systems','permissions'].includes(screen.id)" @click="action(row,'edit')">编辑</button></div></td></tr><tr v-if="!rows.length"><td :colspan="(screen.columns?.length||1)+1" class="empty">暂无记录。完成相应配置或操作后，记录会显示在这里。</td></tr></tbody></table></div><div class="actions mt-4"><span class="muted">共 {{total}} 条</span><template v-if="['users','catalog','audit','loginlogs'].includes(screen.id)"><button :disabled="page===0" @click="page--;refresh()">上一页</button><span class="p-2">第 {{page+1}} 页</span><button :disabled="(page+1)*25>=total" @click="page++;refresh()">下一页</button></template></div></template>
 <form v-if="editor" class="editor" @submit.prevent="save"><h2>{{mode==='create'?'新增记录':`操作对象：${selected?.name||selected?.display_name||selected?.id}`}}</h2><div class="fields"><template v-if="mode==='create'||mode==='edit'"><label v-for="field in screen.fields" :key="field.key">{{field.label}}<input v-model="form[field.key]" :type="field.type||'text'" :required="!field.optional" :min="field.type==='number'?1:undefined" :disabled="mode==='edit'&&field.key==='username'" maxlength="128"></label><label v-if="mode==='edit'&&['users','systems'].includes(screen.id)" class="check"><input v-model="form.enabled" type="checkbox">启用</label></template><label v-if="mode==='password'">初始密码<input v-model="newPassword" type="password" required minlength="8" autocomplete="new-password"><span class="muted text-sm">至少 8 位，大小写、数字、符号中至少三类。</span></label><label v-if="['grant','revoke'].includes(mode)">角色编号<input v-model="roleId" type="number" min="1" required><span class="muted text-sm">从角色管理列表中核对编号。</span></label><label v-if="['grantPermission','revokePermission'].includes(mode)">权限编号<input v-model="permissionId" type="number" min="1" required></label><label v-if="mode==='template'">权限模板<select v-model="templateName"><option v-for="t in ['系统管理员','公司领导','部门经理','项目经理','普通员工']">{{t}}</option></select></label></div><div class="actions"><button class="primary" :disabled="busy">确认保存</button><button type="button" @click="editor=false">取消</button></div></form>
 <form v-if="screen.id==='profile'" @submit.prevent="changePassword"><h2>修改本人密码</h2><div class="fields"><label>原密码<input v-model="oldPassword" type="password" required autocomplete="current-password"></label><label>新密码<input v-model="newPassword" type="password" required minlength="8" autocomplete="new-password"></label></div><p class="muted mb-4">至少 8 位，大小写、数字、符号中至少三类。提交成功后请重新登录。</p><button class="primary" :disabled="busy">修改密码</button></form>
 <form v-if="screen.id==='approvals'" class="editor" @submit.prevent="run(async()=>{await api('/api/platform/self/applications','POST',{roleId:Number(roleId)});await refresh();notify('申请已提交，等待 OA 审批。')})"><h2>申请岗位角色</h2><label style="max-width:400px">岗位角色编号<input v-model="roleId" type="number" min="1" required></label><button class="primary mt-4" :disabled="busy">提交申请</button></form>
 <section v-if="screen.id==='expenses'"><p class="notice">演示数据：仅测试当前登录身份是否具备 expense:list。</p><button class="primary" :disabled="busy" @click="run(async()=>{result=await api('/api/demo/expenses');notify('200：访问成功，返回演示数据。')})">以当前身份访问报销示例</button></section>
 <pre v-if="result" class="mt-5">{{JSON.stringify(result,null,2)}}</pre>
 </template></main></div>
</template>
